import React, { useState } from 'react'

export default function TextForm(props) {
    const handleUpClick=()=>{
        // console.log("Upper Case was Clicked"+text);
        let newText=text.toUpperCase();
        setText(newText);
        props.showalert("Converted to UpperCase","success")
    }
    const handleDownClick=()=>{
        // console.log("Upper Case was Clicked"+text);
        let newText=text.toLowerCase();
        setText(newText);
        props.showalert("Converted to LowerCase","success")
    }
    const handleClearClick=()=>{
        // console.log("Upper Case was Clicked"+text);
        setText("");
        props.showalert("Text cleared Successfull","success")
    }
    const handleOnChange=(event)=>{
        // console.log("On change");
        setText(event.target.value);
    }

    const handleCopy=()=>{
      console.log("Text copied");
      // var text=document.getElementById("myBox");
      // text.select();
      navigator.clipboard.writeText(text);
      props.showalert("Copied Text","success")
    }

    const handleExtraSpaces=()=>{
      let newText=text.split(/[ ]+/);
      setText(newText.join(" "))
      props.showalert("Extra Spaced Removed","success")
    }
    const [text, setText]= useState('');
    // text="new text";  //Wrong way to change the state
    // setText("Nextt");
  return (
    <>
      <div className='container' style={{color:props.mode==='light'?'black':'white'}}>
        <h1>{props.heading}</h1>
        <div className="mb-3">
            <textarea className="form-control" placeholder='Type Something here' value={text} onChange={handleOnChange} style={{backgroundColor:props.mode==='light'?'white':'#3e3333',color:props.mode==='light'?'black':'white'}} id="myBox" rows="8"></textarea>
        </div>
        <button disabled={text.length===0} className="btn btn-primary mx-2 my-2" onClick={handleDownClick}>Convert to LowerCase</button>
        <button disabled={text.length===0} className="btn btn-primary mx-2 my-2" onClick={handleClearClick}>Clear All</button>
        <button disabled={text.length===0} className="btn btn-primary mx-2 my-2" onClick={handleUpClick}>Convert to UpperCase</button>
        <button disabled={text.length===0} className="btn btn-primary mx-2 my-2" onClick={handleCopy}>Copy Text</button>
        <button disabled={text.length===0} className="btn btn-primary mx-2 my-2" onClick={handleExtraSpaces}>Remove Extra Spaces</button>
      </div>
      <div className="container my-2" style={{color:props.mode==='light'?'black':'white'}}>
        <h2>Your Text summary</h2>
        <p>{text.split(/\s+/).filter((element)=>{return element.length!==0}).length} words {text.length} characters</p>
        <p>{0.008 * text.split(" ").filter((element)=>{return element.length!==0}).length} Minutes to read</p>
        <h2>Preview</h2>
        <p>{text.length>0?text:"Enter Something in textbox to preview here"}</p>
      </div>
      </>
  )
}
